From 68ad851d7fa3f95d304220993b5fa2c47b1f3d5e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:54:40 +0100
Subject: [PATCH] applets/notifications: send popups hidden by Do Not Disturb
 to history

Popups on screen when Do Not Disturb turned on were only hidden, so they
popped up again with a fresh timeout once it turned off. Mark them as
expired instead, so they stay in the history like any other popup.

BUG: 524749
---
 applets/notifications/global/Globals.qml | 21 ++++++++++++++++++++-
 1 file changed, 20 insertions(+), 1 deletion(-)

diff --git a/applets/notifications/global/Globals.qml b/applets/notifications/global/Globals.qml
index 8e8e56f88d..cbb3dfc360 100644
--- a/applets/notifications/global/Globals.qml
+++ b/applets/notifications/global/Globals.qml
@@ -37,7 +37,9 @@ QtObject {
         // so it's not considered "added while inhibited" and shown in history unwanted.
         NotificationManager.Server.inhibited = inhibited;

-        if (!inhibited) {
+        if (inhibited) {
+            expirePopupsHiddenByInhibition();
+        } else {
             const urgency = notificationSettings.lowPriorityHistory ? NotificationManager.Notifications.LowUrgency : NotificationManager.Notifications.NormalUrgency;
             popupNotificationsModel.showInhibitionSummary(urgency, notificationSettings.popupBlacklistedApplications, notificationSettings.popupBlacklistedServices);
         }
@@ -311,6 +313,23 @@ QtObject {
         notificationSettings.save();
     }

+    // Popups that Do Not Disturb hides go to the history, so they don't pop up again once it ends
+    function expirePopupsHiddenByInhibition() {
+        const model = popupNotificationsModel;
+        for (let i = model.rowCount() - 1; i >= 0; --i) {
+            const idx = model.index(i, 0);
+            if (model.data(idx, NotificationManager.Notifications.TypeRole) !== NotificationManager.Notifications.NotificationType
+                || model.data(idx, NotificationManager.Notifications.UserActionFeedbackRole)
+                || (model.data(idx, NotificationManager.Notifications.UrgencyRole) === NotificationManager.Notifications.CriticalUrgency
+                    && notificationSettings.criticalPopupsInDoNotDisturbMode)
+                || notificationSettings.doNotDisturbPopupWhitelistedApplications.includes(model.data(idx, NotificationManager.Notifications.DesktopEntryRole))
+                || notificationSettings.doNotDisturbPopupWhitelistedServices.includes(model.data(idx, NotificationManager.Notifications.NotifyRcNameRole))) {
+                continue;
+            }
+            model.setData(idx, true, NotificationManager.Notifications.ExpiredRole);
+        }
+    }
+
     function rectIntersect(rect1 /*dialog*/, rect2 /*popup*/) {
         return rect1.x < rect2.x + rect2.width
                 && rect2.x < rect1.x + rect1.width
